  } catch {
    /* A malformed response cannot grant cleanup permissions without a safe run identity. */
  }
}

function reserveCleanup(url: URL, opts: HttpOptions): boolean {
  if (
    url.hostname !== "api.apify.com" ||
    opts.method !== "POST" ||
    url.hash ||
    opts.body !== undefined
